LAW='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15358.htm'
LEP='https://www.planalto.gov.br/ccivil_03/leis/l7210.htm'
S347='https://scon.stj.jus.br/SCON/pesquisar.jsp?b=SUMU&livre=%22347%22+INPATH%28NUM%29'
S448='https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=30&sumula=1600'
FREE='https://noticias.stf.jus.br/postsnoticias/ministro-do-stf-concede-alvara-de-soltura-para-sergio-jacome-de-lucena/'
T1068='https://portal.stf.jus.br/jurisprudenciarepercussao/verAndamentoProcesso.asp?classeProcesso=RE&incidente=5776893&numeroProcesso=1235340&numeroTema=1068'
T1087='https://portal.stf.jus.br/jurisprudenciaRepercussao/verAndamentoProcesso.asp?classeProcesso=RE&incidente=5745131&numeroProcesso=1225185&numeroTema=1087'
rows={}
def add(n,s,p,a,c,v,q,t,d,links=()):
 rows['art-'+str(n)]=dict(simples=s,pontos=p,atencao=[a],exemplo=c+' Variação: '+v,prova=q,termos=[dict(termo=t,significado=d)],remissoes=[CPP,*links])
add(583,'Subida do RESE nos autos ou traslado depende da hipótese e preservação do andamento, com integração de incisos revogados.', ['Recurso de ofício só onde atualmente cabível.', 'Não restaurar art.581,VI revogado.', 'Pronúncia com pluralidade e condições do parágrafo: traslado.'], 'Não interromper automaticamente processo de corréu que não recorreu nem recuperar RESE de impronúncia eliminado.', 'Um acusado aceita pronúncia e outro recorre: examinar traslado previsto.', 'Impronúncia atual segue apelação, não remissão residual ao incisoVI.', ['Inciso revogado volta pela remissão? Não.', 'Pluralidade pode exigir traslado? Sim.'], 'Forma de subida','Encaminhamento compatível com recurso e continuidade.')
add(584,'Efeitos do RESE são delimitados; Lei15358/2026 acrescentou pedido de efeito suspensivo ou ativo nas hipóteses do art.581,V.', ['Pronúncia suspende só julgamento; quebra de fiança só perda da metade.', 'Novo§4º: até julgamento, pedir ao tribunal com relevância, plausibilidade e risco de dano grave.', 'Retratação do art.589 permanece.', 'Livramento/unificação e multa exigem integração à LEP e reformas.', 'Impronúncia segue apelação atual, não RESE antigo.'], 'Não afirmar que todo RESE suspende tudo ou que efeito ativo novo é automático.', 'Recorrente fundamenta urgência e plausibilidade ao pedir efeito na hipóteseV.', 'Pedido sem risco demonstrado não tem deferimento necessário.', ['Novo efeito é automático? Não.', 'Pronúncia suspende só julgamento pela regra? Sim.'], 'Efeitos recursais','Consequências delimitadas e tutela requerida ao tribunal.',[LAW,LEP])
add(585,'Exigência histórica de prender ou afiançar para recorrer da pronúncia não é condição automática atual de acesso ao recurso.', ['Distinguir admissibilidade recursal e custódia cautelar.', 'Preventiva exige fundamentos próprios e garantias.', 'STF rechaça custódia imposta apenas para admitir recurso.'], 'Não ordenar prisão só para permitir que réu recorra nem negar processamento por estar solto.', 'Réu solto impugna pronúncia pelo recurso cabível.', 'Risco cautelar concreto é questão independente, não preço para acessar tribunal.', ['Prisão é preço obrigatório para recorrer? Não.', 'Cautelar precisa base própria? Sim.'], 'Recurso e liberdade','Garantia recursal separada dos pressupostos de custódia.',[FREE])
add(586,'RESE voluntário tem prazo de cinco dias; lista geral de jurados tem vinte dias da publicação definitiva na hipóteseXIV.', ['Distinguir interposição de razões em dois dias.', 'Marco da exceção é lista definitiva, não provisória.'], 'Não aplicar cinco dias indistintamente à impugnação da lista nem vinte a todo RESE.', 'Decisão de pronúncia é impugnada no prazo pertinente de cinco.', 'Inclusão/exclusão da lista na hipóteseXIV usa vinte dias do marco próprio.', ['Exceção da lista tem vinte dias? Sim.', 'Razões do art.588 têm mesmo prazo sempre? Não.'], 'Prazo do RESE','Interposição com exceção expressa.')
add(587,'Recurso por instrumento exige peças indicadas e essenciais, com traslado conferido em cinco dias.', ['Decisão recorrida, prova de ciência quando necessária e termo de interposição.', 'Integrar peças eletrônicas autênticas e regime do órgão.'], 'Não enviar instrumento incapaz de mostrar decisão ou tempestividade nem exigir papel exclusivo sem regime atual.', 'Parte seleciona peças e inclui decisão/ciência pertinentes.', 'Documento sem identificação não demonstra por si marco recursal.', ['Peças essenciais devem constar? Sim.', 'Tempestividade pode ser ignorada? Não.'], 'Instrumento recursal','Conjunto necessário à compreensão e admissibilidade.')
add(588,'Razões de RESE são oferecidas em dois dias do marco legal; recorrido tem igual prazo, com ciência defensiva se réu.', ['Marco: interposição ou vista após traslado na hipótese.', 'Não confundir com cinco da interposição.', 'Intimar defensor do réu recorrido.'], 'Não omitir ciência da defesa sob justificativa de prazo curto.', 'Após vista pertinente, recorrente fundamenta e recorrido responde.', 'Réu recorrido precisa da intimação ao defensor, não mera nota interna.', ['Razões têm dois dias? Sim.', 'Defensor do réu recorrido deve ser intimado? Sim.'], 'Razões do RESE','Fundamentação e contraditório em prazo próprio.')
add(589,'Após resposta ou seu prazo, juiz em dois dias reforma ou sustenta decisão e instrui recurso.', ['Retratação integra processamento.', 'Se reformar, outra parte pode recorrer por petição quando cabível.', 'Juiz não pode modificar novamente nessa hipótese.', 'Subida sem novos arrazoados nas condições legais.'], 'Não criar sequência infinita de retratações nem suprimir direito da parte contrária.', 'Juiz revê decisão e parte contrária apresenta recurso cabível por petição.', 'Sustentar decisão não impede encaminhamento ao tribunal.', ['Juiz pode modificar indefinidamente nesse parágrafo? Não.', 'Retratação pode gerar recurso da parte contrária? Sim.'], 'Retratação','Reexame pelo próprio juiz antes do tribunal.')
add(590,'Se traslado não puder ser extraído no prazo, juiz pode prorrogá-lo até o dobro.', ['Prorrogação judicial, não livre prazo da parte.', 'Integrar impossibilidade real e registro.'], 'Não duplicar prazo de interposição do recorrente por conta desta regra da secretaria.', 'Dificuldade comprovada permite prazo maior para extrair instrumento.', 'Parte não ganha dez dias para interpor RESE só porque traslado é demorado.', ['Prorrogação dobra prazo de interposição? Não.', 'Refere-se à extração do traslado? Sim.'], 'Prorrogação do traslado','Dilação do trabalho de formação do instrumento.')
add(591,'Encaminhamento ao órgão ad quem ocorre em cinco dias da resposta do juízo a quo, com integração ao sistema eletrônico.', ['Distinguir remessa e prazo de recorrer.', 'Correio é previsão histórica de transmissão, não exclusividade atual.'], 'Não aplicar esses cinco dias como nova oportunidade de interposição tardia.', 'Secretaria encaminha recurso já processado ao competente.', 'Remessa eletrônica válida não precisa virar carta física por literalidade.', ['É prazo de encaminhamento? Sim.', 'Cria novo prazo para recurso perdido? Não.'], 'Remessa do RESE','Transmissão administrativa ao órgão julgador.')
add(592,'Após publicada decisão recursal, autos retornam ao juízo de origem no prazo previsto de cinco dias, integrado à tramitação atual.', ['Não confundir retorno com fim de todo recurso possível.', 'Verificar comunicações e providências pertinentes.'], 'Devolver autos não significa trânsito em julgado automático de qualquer decisão.', 'Secretaria devolve após julgamento para providências do juízo.', 'Possibilidade de recurso cabível deve ser examinada separadamente.', ['Retorno implica sempre trânsito imediato? Não.', 'Há prazo textual de cinco dias? Sim.'], 'Retorno dos autos','Encaminhamento após decisão do recurso.')
add(593,'Apelação em cinco dias abrange sentenças do singular e hipóteses específicas do júri, com consequências diferentes.', ['Júri: nulidade após pronúncia, sentença contrária à lei/veredito, erro de pena ou manifesta contrariedade à prova.', 'Lei/veredito/pena: tribunal retifica no âmbito pertinente.', 'Contrariedade manifesta: novo júri, sem segunda apelação pelo mesmo motivo.', 'Cabível apelação, não escolher RESE deliberadamente; fungibilidade tem requisitos.', 'Tema1087 integra absolvição genérica e clemência constitucional registrada.'], 'Tribunal não substitui livremente jurados para condenar só por discordar de prova.', 'Erro na pena é corrigido pelo tribunal na hipótese própria.', 'Veredito manifestamente contrário à prova pode levar a novo júri, não condenação direta por mera reavaliação.', ['Erro de pena e novo júri têm mesma consequência? Não.', 'Prazo geral de interposição é cinco dias? Sim.'], 'Apelação penal','Revisão da decisão nos fundamentos e efeitos legais.',[T1087])
add(596,'Recurso da absolvição não impede liberdade imediata se não houver outro título prisional; parágrafo de medida provisória exige integração histórica.', ['Não antecipar culpa porque acusação recorreu.', 'Segurança penal não se impõe por antiga referência automática.', 'Verificar outro fundamento legítimo de custódia.'], 'Não conservar prisão só pela apelação acusatória nem restaurar medida provisória do regime antigo.', 'Absolvido sem outro título é libertado apesar do recurso.', 'Prisão por processo diverso exige decisão própria, não liberação indiscriminada de todos os títulos.', ['Apelação acusatória impede por si liberdade? Não.', 'Outro título prisional exige exame? Sim.'], 'Efeito da absolvição','Liberdade vinculada à decisão e demais títulos válidos.')
add(597,'Apelação condenatória tem efeito suspensivo no regime comum, integrado à exceção atual do júri e remissões históricas.', ['Art.393 revogado não volta.', 'Interdições/segurança provisórias antigas não são regime atual geral.', 'Tema1068/STF: condenação do júri tem execução independente do total da pena.', 'Cautelar válida é questão própria.'], 'Não afirmar que toda condenação em qualquer rito aguarda apelação nem que toda sentença comum permite execução automática.', 'Condenação comum e prisão cautelar são examinadas por bases distintas.', 'Júri exige integrar precedente específico, mesmo pena inferior a quinze.', ['Júri e sentença comum têm sempre mesmo efeito? Não.', 'Remissão restaura art.393 revogado? Não.'], 'Efeito suspensivo integrado','Regra e exceções lidas com reformas e precedentes.',[T1068])
add(598,'Sem apelação do MP, ofendido/legitimados podem recorrer supletivamente; prazo distingue habilitação.', ['Não habilitado: quinze dias após prazo do MP no regime do artigo.', 'Assistente habilitado: cinco dias, com ciência regular e leitura da Súmula448/STF.', 'Recurso da hipótese não tem efeito suspensivo.', 'Não presumir autorização de qualquer terceiro interessado.'], 'Não aplicar quinze dias a todo assistente nem iniciar prazo sem examinar ciência e inércia ministerial.', 'Ofendido não habilitado recorre na hipótese de omissão do MP pelo prazo pertinente.', 'Assistente já habilitado exige prazo próprio de cinco e intimação válida.', ['Todo assistente tem quinze dias? Não.', 'Não habilitado tem hipótese supletiva? Sim.'], 'Recurso supletivo','Impugnação diante da inércia do acusador público.',[S448])
add(599,'Apelação pode atingir todo julgado ou parte dele.', ['Identificar capítulos impugnados.', 'Integrar limites e efeitos legais do recurso.'], 'Recurso parcial não é autorização para agravar livremente parte não impugnada pela acusação.', 'Defesa impugna dosimetria sem contestar todo fundamento.', 'Pedido limitado exige examinar âmbito devolvido e garantias, não refazer processo indiscriminadamente.', ['Apelação pode ser parcial? Sim.', 'Pedido parcial elimina garantias recursais? Não.'], 'Objeto da apelação','Parte da decisão levada ao tribunal.')
add(600,'Razões/contrarrazões da apelação têm oito dias cada; contravenção três; interposição é prazo distinto.', ['Assistente: três após MP; ação privada: vista ao MP por três.', 'Vários apelantes/apelados: prazos comuns.', 'Opção de arrazoar no tribunal deve ser declarada na interposição e observar ciência/prazos.', 'Defesa efetiva não é dispensada por inércia do advogado.'], 'Não confundir oito dias das razões com cinco da interposição nem avançar sem garantir defesa diante de omissão.', 'Parte interpõe em cinco e apresenta razões no prazo pertinente de oito.', 'Contravenção tem três para razões no regime deste artigo.', ['Razões ordinárias têm oito dias? Sim.', 'Interposição geral ganha oito por isso? Não.'], 'Razões de apelação','Fundamentação em fase e prazo próprios.')
add(601,'Após prazo de razões, remeter autos ao superior com ou sem elas, com regimes próprios de traslado e garantias.', ['Texto: cinco dias, com exceção de trinta referida.', 'Pluralidade e julgamento/recurso parciais podem exigir instrumento no regime descrito.', 'Custos não cobrados do réu pobre ou MP na hipótese de traslado.', 'Não suprimir assistência defensiva por falta de razões.'], 'Subida sem razões no texto não permite ignorar defesa técnica efetiva nem impor despesas incompatíveis com gratuidade.', 'Secretaria remete processo e controla regularidade defensiva.', 'Falta do advogado exige providência pertinente antes de presumir abandono irreversível.', ['Texto prevê subida com ou sem razões? Sim.', 'Isso elimina garantia de defesa? Não.'], 'Subida da apelação','Remessa com controle de atos e garantias.')
add(602,'Encaminhar apelação nos prazos do art.601 ao tribunal, integrando previsão postal à tramitação eletrônica válida.', ['Transmissão documentada.', 'Não confundir prazo administrativo e admissibilidade do recurso.'], 'Texto de correio sob registro não impõe exclusivamente envio físico hoje.', 'Órgão registra remessa eletrônica regular ao tribunal.', 'Falha de transmissão exige apuração e correção, não ocultar perda do recurso.', ['Correio é única via atual obrigatória? Não.', 'Registro da transmissão importa? Sim.'], 'Transmissão da apelação','Encaminhamento formal e rastreável.')
add(603,'Texto prevê subida nos originais e preservação de peças essenciais; referências organizacionais antigas exigem integração atual.', ['Autos eletrônicos têm modo válido de acesso e remessa.', 'Distinguir conservação documental e duplicação física indiscriminada.', 'Não restaurar libelo ou curador por remissão ao art.564.'], 'Nome antigo de tribunal e cidade não resolve sozinho regra eletrônica atual.', 'Processo digital sobe com acesso íntegro das peças pertinentes.', 'Não exigir documento antigo do rito extinto só porque remissão menciona essenciais.', ['Remissão recupera libelo extinto? Não.', 'Integridade documental deve ser preservada? Sim.'], 'Autos e peças essenciais','Documentação íntegra para julgamento recursal.')
assert len(rows)==19
Path(sys.argv[1]).write_text(json.dumps({'course_slug':'codigo-processo-penal','units':rows},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(rows),'appeal processing units reviewed')
